import AppKit
import RunbarCore
import SwiftUI

/// What a service runs, for the icon beside its name: the config's `type`, the database behind a proxy (or
/// any service on a database port), and for Node the framework in package.json.
enum ServiceKind: Equatable {
    case nextjs, node, astro, vite, python, docker, java, postgres, mysql, redis, proxy, other

    var label: String {
        switch self {
        case .nextjs: return "Next.js"
        case .node: return "Node.js"
        case .astro: return "Astro"
        case .vite: return "Vite"
        case .python: return "Python"
        case .docker: return "Docker"
        case .java: return "Java"
        case .postgres: return "PostgreSQL"
        case .mysql: return "MySQL"
        case .redis: return "Redis"
        case .proxy: return "Proxy"
        case .other: return "Command"
        }
    }

    /// Kinds without a brand mark use an SF Symbol.
    var symbol: String { self == .proxy ? "arrow.left.arrow.right" : "terminal" }

    @MainActor private static var cache: [String: (key: String, kind: ServiceKind)] = [:]

    /// Cached per service until its type, command, folder, port or URL change (package.json is read once).
    @MainActor static func of(_ cfg: ServiceConfig) -> ServiceKind {
        let key = "\(cfg.type.rawValue)|\(cfg.command)|\(cfg.cwd)|\(cfg.port ?? 0)|\(cfg.open ?? "")"
        if let hit = cache[cfg.id], hit.key == key { return hit.kind }
        let kind = detect(cfg)
        cache[cfg.id] = (key, kind)
        return kind
    }

    static func detect(_ cfg: ServiceConfig) -> ServiceKind {
        switch cfg.type {
        case .nextjs: return .nextjs
        case .python: return .python
        case .java: return .java
        case .node: return framework(cfg) ?? .node
        case .docker: return database(cfg) ?? .docker
        case .proxy: return database(cfg) ?? .proxy
        case .other: return database(cfg) ?? .other
        }
    }

    /// From the URL's scheme, the command, then the port.
    private static func database(_ cfg: ServiceConfig) -> ServiceKind? {
        let scheme = cfg.url(port: cfg.port)?.scheme?.lowercased() ?? ""
        if scheme.hasPrefix("postgres") { return .postgres }
        if scheme.hasPrefix("mysql") || scheme.hasPrefix("mariadb") { return .mysql }
        if scheme.hasPrefix("redis") { return .redis }
        let c = cfg.command.lowercased()
        if c.contains("postgres") || c.contains("psql") { return .postgres }
        if c.contains("mysql") || c.contains("mariadb") { return .mysql }
        if c.contains("redis") { return .redis }
        switch cfg.port ?? 0 {
        case 5432...5439: return .postgres
        case 3306, 3307: return .mysql
        case 6379, 6380: return .redis
        default: return nil
        }
    }

    private static func framework(_ cfg: ServiceConfig) -> ServiceKind? {
        let c = cfg.command.lowercased()
        if c.contains("astro") { return .astro }
        if c.contains("vite") { return .vite }
        guard !cfg.cwd.isEmpty,
              let text = try? String(contentsOfFile: (cfg.cwd as NSString).appendingPathComponent("package.json"), encoding: .utf8)
        else { return nil }
        if text.contains("\"astro\"") { return .astro }
        if text.contains("\"vite\"") { return .vite }
        return nil
    }

