    @MainActor private static var parsed: [String: Path] = [:]

    @MainActor var mark: Path? {
        guard let d = svgPath else { return nil }
        if let hit = Self.parsed[d] { return hit }
        let path = Path(SVGPath.parse(d))
        Self.parsed[d] = path
        return path
    }
}

/// A brand mark (24 pt viewBox) scaled to its frame.
private struct BrandShape: Shape {
    let mark: Path
    func path(in rect: CGRect) -> Path {
        mark.applying(CGAffineTransform(scaleX: rect.width / 24, y: rect.height / 24).concatenating(CGAffineTransform(translationX: rect.minX, y: rect.minY)))
    }
}

/// What the service runs, in a small tile, with its status dot on the tile's corner.
struct ServiceIcon: View {
    let config: ServiceConfig
    let dot: ServiceDisplay.Dot
    var size: CGFloat = Layout.icon

    var body: some View {
        let kind = ServiceKind.of(config)
        let stopped = dot == .stopped
        let glyph = size * 0.6
        let dotSize: CGFloat = size >= 24 ? 8 : 7
        let shape = RoundedRectangle(cornerRadius: size * 0.3, style: .continuous)
        ZStack {
            shape.fill(stopped ? Color.rbControl.opacity(0.6) : Color.rbControl)
            Group {
                if let mark = kind.mark {
                    BrandShape(mark: mark).frame(width: glyph, height: glyph)
                } else {
                    Image(systemName: kind.symbol).font(.system(size: glyph * 0.85, weight: .semibold))
                }
            }
            .foregroundStyle(stopped ? Color.rbText3 : Color.rbTextDim)
        }
        .frame(width: size, height: size)
        // A ring cut out of the tile around the dot, so the dot reads on any background (glass included).
        .mask {
            Rectangle()
                .overlay(alignment: .bottomTrailing) {
                    Circle()
                        .frame(width: dotSize + 4, height: dotSize + 4)
                        .offset(x: 5, y: 5)
                        .blendMode(.destinationOut)
                }
                .compositingGroup()
        }
        .overlay(alignment: .bottomTrailing) {
            StatusDot(dot: dot, size: dotSize, halo: false).offset(x: 3, y: 3)
        }
        .help(kind.label)
        .accessibilityHidden(true)
    }
}

/// SVG path data to a CGPath: every command, arcs included, absolute and relative.
enum SVGPath {
    static func parse(_ d: String) -> CGPath {
        let path = CGMutablePath()
        var s = Scanner(Array(d.utf8))
        var current = CGPoint.zero
        var start = CGPoint.zero
        var lastCubic: CGPoint?
        var lastQuad: CGPoint?
        var cmd: UInt8 = 0

        func point(_ base: CGPoint, _ rel: Bool) -> CGPoint {
            let x = s.number(), y = s.number()
            return rel ? CGPoint(x: base.x + x, y: base.y + y) : CGPoint(x: x, y: y)
        }
        func reflect(_ p: CGPoint?) -> CGPoint {
            guard let p else { return current }
            return CGPoint(x: 2 * current.x - p.x, y: 2 * current.y - p.y)
        }

        while true {
            if let c = s.command() {
                cmd = c
            } else if s.hasNumber(), cmd != 0, cmd | 0x20 != UInt8(ascii: "z") {
                // More numbers repeat the command; after a move they are lines.
                if cmd == UInt8(ascii: "M") { cmd = UInt8(ascii: "L") } else if cmd == UInt8(ascii: "m") { cmd = UInt8(ascii: "l") }
            } else {
                break
            }
            let rel = cmd >= UInt8(ascii: "a")
            var cubic: CGPoint?
            var quad: CGPoint?
            switch cmd | 0x20 {
            case UInt8(ascii: "m"):
                current = point(current, rel)
                start = current
                path.move(to: current)
            case UInt8(ascii: "l"):
                current = point(current, rel)
                path.addLine(to: current)
            case UInt8(ascii: "h"):
                let x = s.number()
                current.x = rel ? current.x + x : x
                path.addLine(to: current)
            case UInt8(ascii: "v"):
                let y = s.number()
                current.y = rel ? current.y + y : y
                path.addLine(to: current)
            case UInt8(ascii: "c"):
                let c1 = point(current, rel), c2 = point(current, rel), p = point(current, rel)
                path.addCurve(to: p, control1: c1, control2: c2)
                cubic = c2
                current = p
            case UInt8(ascii: "s"):
                let c1 = reflect(lastCubic), c2 = point(current, rel), p = point(current, rel)
                path.addCurve(to: p, control1: c1, control2: c2)
                cubic = c2
                current = p
            case UInt8(ascii: "q"):
                let c = point(current, rel), p = point(current, rel)
                path.addQuadCurve(to: p, control: c)
                quad = c
                current = p
            case UInt8(ascii: "t"):
                let c = reflect(lastQuad), p = point(current, rel)
                path.addQuadCurve(to: p, control: c)
                quad = c
                current = p
            case UInt8(ascii: "a"):
                let rx = s.number(), ry = s.number(), angle = s.number()
                let large = s.flag(), sweep = s.flag()
                let p = point(current, rel)
                arc(path, from: current, to: p, rx: rx, ry: ry, degrees: angle, large: large, sweep: sweep)
                current = p
            case UInt8(ascii: "z"):
                path.closeSubpath()
                current = start
            default:
                return path
            }
            lastCubic = cubic
            lastQuad = quad
        }
        return path
    }

    /// SVG's endpoint arc as an arc of the unit circle, scaled, rotated and moved into place.
    private static func arc(_ path: CGMutablePath, from p0: CGPoint, to p: CGPoint, rx: CGFloat, ry: CGFloat,
                            degrees: CGFloat, large: Bool, sweep: Bool) {
        guard p0 != p else { return }
        var rx = abs(rx), ry = abs(ry)
        guard rx > 0, ry > 0 else { return path.addLine(to: p) }
        let phi = degrees * .pi / 180
        let cosP = cos(phi), sinP = sin(phi)
        let dx = (p0.x - p.x) / 2, dy = (p0.y - p.y) / 2
        let x1 = cosP * dx + sinP * dy
        let y1 = -sinP * dx + cosP * dy
        let lambda = (x1 * x1) / (rx * rx) + (y1 * y1) / (ry * ry)
        if lambda > 1 { rx *= lambda.squareRoot(); ry *= lambda.squareRoot() }
        let num = rx * rx * ry * ry - rx * rx * y1 * y1 - ry * ry * x1 * x1
        let den = rx * rx * y1 * y1 + ry * ry * x1 * x1
        var k = den == 0 ? 0 : max(0, num / den).squareRoot()
        if large == sweep { k = -k }
        let cx1 = k * rx * y1 / ry
        let cy1 = -k * ry * x1 / rx
        let cx = cosP * cx1 - sinP * cy1 + (p0.x + p.x) / 2
        let cy = sinP * cx1 + cosP * cy1 + (p0.y + p.y) / 2
        func angle(_ ux: CGFloat, _ uy: CGFloat, _ vx: CGFloat, _ vy: CGFloat) -> CGFloat {
            atan2(ux * vy - uy * vx, ux * vx + uy * vy)
        }
        let start = angle(1, 0, (x1 - cx1) / rx, (y1 - cy1) / ry)
        var delta = angle((x1 - cx1) / rx, (y1 - cy1) / ry, (-x1 - cx1) / rx, (-y1 - cy1) / ry)
        if !sweep && delta > 0 { delta -= 2 * .pi } else if sweep && delta < 0 { delta += 2 * .pi }
        let t = CGAffineTransform(translationX: cx, y: cy).rotated(by: phi).scaledBy(x: rx, y: ry)
        path.addArc(center: .zero, radius: 1, startAngle: start, endAngle: start + delta, clockwise: delta < 0, transform: t)
    }

    private struct Scanner {
        let bytes: [UInt8]
        var i = 0
        init(_ bytes: [UInt8]) { self.bytes = bytes }

        private static func isDigit(_ c: UInt8) -> Bool { c >= 48 && c <= 57 }

        mutating func skip() {
            while i < bytes.count, [32, 44, 9, 10, 13].contains(bytes[i]) { i += 1 }
        }

        mutating func command() -> UInt8? {
            skip()
            guard i < bytes.count else { return nil }
            let c = bytes[i] | 0x20
            guard c >= UInt8(ascii: "a"), c <= UInt8(ascii: "z"), c != UInt8(ascii: "e") else { return nil }
            defer { i += 1 }
            return bytes[i]
        }

        mutating func hasNumber() -> Bool {
            skip()
            guard i < bytes.count else { return false }
            let c = bytes[i]
            return Self.isDigit(c) || c == UInt8(ascii: "-") || c == UInt8(ascii: "+") || c == UInt8(ascii: ".")
        }

        /// "1.5.5" is 1.5 then .5, "1-2" is 1 then -2.
        mutating func number() -> CGFloat {
            skip()
            let from = i
            if i < bytes.count, bytes[i] == UInt8(ascii: "-") || bytes[i] == UInt8(ascii: "+") { i += 1 }
            while i < bytes.count, Self.isDigit(bytes[i]) { i += 1 }
            if i < bytes.count, bytes[i] == UInt8(ascii: ".") {
                i += 1
                while i < bytes.count, Self.isDigit(bytes[i]) { i += 1 }
            }
            if i < bytes.count, bytes[i] | 0x20 == UInt8(ascii: "e") {
                var j = i + 1
                if j < bytes.count, bytes[j] == UInt8(ascii: "-") || bytes[j] == UInt8(ascii: "+") { j += 1 }
                if j < bytes.count, Self.isDigit(bytes[j]) {
                    i = j
                    while i < bytes.count, Self.isDigit(bytes[i]) { i += 1 }
                }
            }
            return CGFloat(Double(String(decoding: bytes[from..<i], as: UTF8.self)) ?? 0)
        }

        /// Arc flags are one character, and may touch what follows ("a1 1 0 011 1").
        mutating func flag() -> Bool {
            skip()
            guard i < bytes.count else { return false }
            defer { i += 1 }
            return bytes[i] == UInt8(ascii: "1")
        }
    }
}
